  if n s= 0%usize
  then Ok 0%usize
  else (
    i <- usize_sub n 1%usize;
    c <- code_CtrlsStack_get st.(code_OpIterState_ctrls) i;
    Ok c.(code_Ctrl_value_stack_base))
.

