Definition code_pop_with_type
  (st : code_OpIterState_t) (expected : types_ValueType_t) :
  result ((core_result_Result_t code_StackType_t error_OpError_t) *
    code_OpIterState_t)
  :=
  p <- code_pop_stack_type st;
  let (r, st1) := p in
  cf <-
    core_result_Result_Insts_CoreOpsTry_traitTryTResultInfallibleE_branch r;
  match cf with
  | Core_ops_control_flow_ControlFlow_Continue val =>
    match val with
    | Code_StackType_Val v =>
      b <- types_ValueType_Insts_CoreCmpPartialEqValueType_eq v expected;
      if b
      then Ok (Core_result_Result_Ok val, st1)
      else Ok (Core_result_Result_Err Error_OpError_TypeMismatch, st1)
    | Code_StackType_Bot => Ok (Core_result_Result_Ok Code_StackType_Bot, st1)
    end
  | Core_ops_control_flow_ControlFlow_Break residual =>
    r1 <-
      core_result_Result_Insts_CoreOpsTry_traitFromResidualResultInfallibleE_from_residual
        code_StackType_t (core_convert_From_Blanket error_OpError_t) residual;
    Ok (r1, st1)
  end
.

