    Source: 'src/reader.rs', lines 66:4-89:5 *)
Definition reader_read_sn_leb_loop
  (data : slice u8) (last : u32) (lo : i128) (hi : i128) (acc : i128)
  (mult : i128) (p : usize) (i : u32) :
  result (core_result_Result_t (i128 * usize) error_OpError_t)
  :=
  loop
    (fun '((acc1, mult1, p1, i1) : (i128 * i128 * usize * u32)) =>
      let i2 := slice_len data in
      if p1 s>= i2
      then Ok (Done (Core_result_Result_Err Error_OpError_UnexpectedEof))
      else (
        b <- slice_index_usize data p1;
        p2 <- usize_add p1 1%usize;
        low <- u8_rem b 128%u8;
        i3 <- scalar_cast U8 I128 low;
        i4 <- i128_mul i3 mult1;
        acc2 <- i128_add acc1 i4;
        if b s< 128%u8
        then (
          acc3 <-
            if low s>= 64%u8
            then (i5 <- i128_mul mult1 128%i128; i128_sub acc2 i5)
            else Ok acc2;
          if acc3 s< lo
          then Ok (Done (Core_result_Result_Err Error_OpError_LebTooLong))
          else
            if acc3 s> hi
            then Ok (Done (Core_result_Result_Err Error_OpError_LebTooLong))
            else Ok (Done (Core_result_Result_Ok (acc3, p2))))
        else
          if i1 s= last
          then Ok (Done (Core_result_Result_Err Error_OpError_LebTooLong))
          else (
            mult2 <- i128_mul mult1 128%i128;
            i5 <- u32_add i1 1%u32;
            Ok (Cont (acc2, mult2, p2, i5)))))
    (acc, mult, p, i)
.

