(** [itasca::code::is_then]:
    Source: 'src/code.rs', lines 993:0-1001:1 *)
Definition code_is_then (kind : code_LabelKind_t) : result bool :=
  match kind with
  | Code_LabelKind_Body => Ok false
  | Code_LabelKind_Block => Ok false
  | Code_LabelKind_Loop => Ok false
  | Code_LabelKind_Then => Ok true
  | Code_LabelKind_Else => Ok false
  end
.

