      Ok (Core_result_Result_Ok (depth, c),
        {|
          code_OpIterState_vals := st.(code_OpIterState_vals);
          code_OpIterState_ctrls := st.(code_OpIterState_ctrls);
          code_OpIterState_pos := p
        |}))
