Definition code_read_return
  (st : code_OpIterState_t) (ctx : code_Context_t) :
  result ((core_result_Result_t unit error_OpError_t) * code_OpIterState_t)
  :=
  bt <-
    match ctx.(code_Context_results) with
    | None => Ok Code_BlockType_Empty
