(** [itasca::limits::validate_limits]:
    Source: 'src/limits.rs', lines 55:0-68:1 *)
Definition limits_validate_limits
  (limits : types_Limits_t) (range : u32) :
  result (core_result_Result_t unit error_Error_t)
  :=
  if limits.(types_Limits_min) s> range
  then Ok (Core_result_Result_Err Error_Error_LimitsOutOfRange)
  else
    match limits.(types_Limits_max) with
    | None => Ok (Core_result_Result_Ok tt)
    | Some max =>
      if max s> range
      then Ok (Core_result_Result_Err Error_Error_LimitsOutOfRange)
      else
        if limits.(types_Limits_min) s> max
        then Ok (Core_result_Result_Err Error_Error_LimitsOutOfRange)
        else Ok (Core_result_Result_Ok tt)
    end
.

